'use strict';
/**
 * UWorld Buzz Fun — Reproductive.
 *
 * One card per UWorld Adventure reproductive question (192, OB-024 … OB-215),
 * cut down to the one concept it tests. Written in our own words — no stem or
 * explanation text is copied. Same rules as the other UWorld decks: the answer
 * matches the wrong answers in style and length, and the explanation is three
 * full sentences.
 *
 * Row: [sourceId, type, topic, clue, answer, [3 wrong answers], [points]]
 * Card id is BFU-<sourceId> (OB-nnn). Run `node server/buzzfun/check.js`.
 */
module.exports = [
  ["OB-024","ASSOCIATION","Cervical disease","Nulliparous woman with CIN 3, three partners over 15 years, douches — the risk factor that matters","Never using condoms",["Early menarche at age 9","Regular vaginal douching","Never having given birth"],["Cervical dysplasia is driven by persistent high-risk HPV infection.","HPV spreads through sexual contact, so unprotected sex raises exposure to oncogenic strains.","Menarche age and parity are risk factors for endometrial and ovarian cancer, not cervical neoplasia."]],
  ["OB-025","ASSOCIATION","Sexual health","Anxious 16-year-old with a vaginal discharge refuses a pelvic exam — next step","Offer a self-collected swab",["Ask her mother for consent","Sedate her and examine anyway","Examine while distracting her"],["A minor can consent to her own sexual health care and can therefore refuse an examination.","Her problem is not an emergency, so her refusal must be respected.","Self-collected vaginal swabs or urine NAAT test accurately for gonorrhea, chlamydia and trichomonas."]],
  ["OB-026","ASSOCIATION","Infertility & PCOS","Obese woman with periods 2–3 times a year, acne and chin hair — long-term risk","Endometrial carcinoma",["Adrenal atrophy","Type 1 diabetes","Cushing syndrome"],["Oligomenorrhea, hyperandrogenism and infertility point to polycystic ovary syndrome.","Without ovulation there is no progesterone, so the endometrium sees unopposed estrogen.","Unopposed estrogen causes endometrial hyperplasia and carcinoma; PCOS also raises the risk of type 2 diabetes."]],
  ["OB-027","MECHANISM","Menstrual cycle & hormones","Normal follicular estradiol rise — the ovarian cell that turns androgens into estradiol","Granulosa cell",["Theca interna cell","Theca externa cell","Leydig cell"],["In the two-cell model, LH drives theca cells to make androgens from cholesterol.","FSH induces aromatase in granulosa cells, which converts those androgens to estradiol.","Theca cells lack aromatase, and Leydig cells are the male counterpart of theca cells."]],
  ["OB-028","ASSOCIATION","Pelvic anatomy","Postmenopausal woman with vaginal pressure and a bulging anterior wall on Valsalva — underlying cause","Pudendal nerve injury",["Uterine leiomyomas","Chronic endometriosis","Uterine artery ligation"],["A vaginal wall bulge with pressure is pelvic organ prolapse.","Stretching of the pudendal nerve during vaginal birth weakens the levator ani and pelvic floor over time.","Low estrogen after menopause and a low BMI further weaken the supporting tissues."]],
  ["OB-029","MECHANISM","Menstrual cycle & hormones","Bleeding a few days after a 10-day course of medroxyprogesterone ends — cellular process","Apoptosis",["Hyperplasia","Dysplasia","Hypertrophy"],["A progestin challenge tests whether the endometrium has been primed by estrogen.","When the progestin stops, the functional layer undergoes programmed cell death and sheds.","Bleeding after withdrawal proves there is enough estrogen and an open outflow tract."]],
  ["OB-030","MECHANISM","Vaginal & pelvic infections","Itchy red vulva with thick white discharge two weeks after antibiotics for a UTI — why","Loss of vaginal lactobacilli",["Less glycogen in vaginal cells","More alkaline cervical mucus","Pinworm eggs around the anus"],["Antibiotics kill the normal gram-positive lactobacilli of the vagina.","Lactobacilli keep the pH acidic and limit yeast, so Candida overgrows without them.","Vulvovaginal candidiasis shows pseudohyphae on KOH and is treated with fluconazole."]],
  ["OB-031","ASSOCIATION","Infertility & PCOS","Infertile woman, normal cycles and normal semen, PID seven years ago treated with ceftriaxone alone — cause","Incompletely treated pelvic infection",["Long-term oral contraceptive use","Chronic ovulatory dysfunction","Advanced maternal age"],["PID is usually caused by Chlamydia trachomatis and Neisseria gonorrhoeae together.","Ceftriaxone alone misses chlamydia, so doxycycline must be added.","Ongoing inflammation scars the fallopian tubes, causing tubal factor infertility and ectopic pregnancy."]],
  ["OB-032","MECHANISM","Breast","Red, swollen breast with dimpled orange-peel skin unresponsive to moisturiser — mechanism of the skin change","Blocked dermal lymphatics",["Foreign body reaction","Deep venous thrombosis","Bacterial infection"],["Peau d'orange with erythema over a third or more of the breast is inflammatory breast cancer.","Tumor emboli block lymphatic channels in the dermis, causing edema around hair follicles.","It is often mistaken for mastitis or dermatitis and carries a poor prognosis."]],
  ["OB-033","ASSOCIATION","Ovarian masses","Postmenopausal bleeding, endometrial hyperplasia and a solid ovarian mass — tumor product","Estrogen",["Beta-hCG","CA-125","Testosterone"],["A solid ovarian mass with endometrial hyperplasia suggests a granulosa cell tumor.","Granulosa cells contain aromatase and secrete estrogen, which stimulates the endometrium.","Histology shows Call-Exner bodies, and inhibin is a tumor marker."]],
  ["OB-034","ASSOCIATION","Ovarian masses","Young woman with new hirsutism, deeper voice, clitoromegaly and an adnexal mass","Sertoli-Leydig cell tumor",["Granulosa cell tumor","Dysgerminoma","Mature teratoma"],["Rapid virilisation with an ovarian mass points to an androgen-secreting tumor.","Sertoli-Leydig cell tumors are sex cord-stromal tumors that make testosterone.","Granulosa cell tumors make estrogen, while dysgerminomas make LDH and sometimes hCG."]],
  ["OB-035","MECHANISM","Contraception & drugs","Endometriosis drug given as a steady depot: FSH and estrogen rise at first, then all fall by week 8","Leuprolide",["Clomiphene","Danazol","Etonogestrel"],["Leuprolide is a GnRH agonist.","Continuous exposure first causes a flare of FSH and LH, then downregulates pituitary GnRH receptors.","The result is low FSH, LH and estrogen, a reversible medical menopause used for endometriosis and fibroids."]],
  ["OB-036","MECHANISM","Disorders of sex development","12-year-old girl with slowing growth, no breast development and tall parents — usual cause of her disorder","Meiotic nondisjunction",["Uniparental disomy","Balanced translocation","Skewed X inactivation"],["Short stature with delayed puberty in a girl suggests Turner syndrome (45,X).","Most cases come from meiotic nondisjunction, usually loss of the paternal sex chromosome.","Gonadal dysgenesis leaves streak ovaries, so estrogen is low and FSH is high."]],
  ["OB-037","ASSOCIATION","Ovarian masses","Sudden severe right pelvic pain with vomiting in a woman with a known 6-cm ovarian cyst","Ovarian torsion",["Acute appendicitis","Ectopic pregnancy","Tubo-ovarian abscess"],["Abrupt unilateral pain with nausea and vomiting in a woman with an adnexal mass is ovarian torsion.","Masses of 5 cm or more make the ovary prone to twisting.","Doppler may show absent flow, but normal flow does not exclude it; treat with urgent laparoscopy."]],
  ["OB-038","MECHANISM","Disorders of sex development","Short woman with a webbed neck and regular periods; 40% of blood cells are 45,X","Somatic mosaicism",["Germline mosaicism","Complete monosomy X","Uniparental disomy"],["Two cell lines in one person after fertilisation is somatic mosaicism.","It arises from mitotic nondisjunction in the early embryo.","Mosaic Turner syndrome is milder, and some women have spontaneous puberty and periods."]],
  ["OB-039","ASSOCIATION","Pelvic anatomy","Postpartum hemorrhage from uterine atony despite massage and uterotonics — artery ligated","Internal iliac",["External iliac","Common iliac","Ovarian"],["Bilateral internal iliac ligation lowers pulse pressure to the uterus and stops atonic bleeding.","The uterine artery is a branch of the anterior division of the internal iliac.","Ligating the external or common iliac would cut off blood to the leg."]],
  ["OB-040","ASSOCIATION","Uterine disorders","Constipation and pelvic pressure with an irregular, enlarged uterus and regular periods","Posterior subserosal fibroid",["Rectovaginal endometriosis","Posterior vaginal prolapse","Adenomyosis"],["An irregularly enlarged uterus is the classic sign of leiomyomas.","Subserosal fibroids grow outward, so a posterior one presses on the rectum and causes constipation.","Submucosal fibroids, by contrast, cause heavy bleeding."]],
  ["OB-041","ASSOCIATION","Cervical disease","Woman with perinatally acquired HIV and missed check-ups has high-grade cervical dysplasia — key risk","Immunosuppression",["Early menarche","Nulliparity","Family history"],["Most HPV infections are cleared by cell-mediated immunity.","In HIV, persistent HPV infection progresses to high-grade dysplasia and cancer more often.","Women with HIV need more frequent cervical screening."]],
  ["OB-042","ASSOCIATION","Vaginal & pelvic infections","Postcoital spotting, yellow discharge and dysuria with a friable cervix — complication if untreated","Tubal factor infertility",["Cervical insufficiency","Early follicle depletion","Cervical cancer"],["Mucopurulent cervicitis with a friable cervix is usually chlamydia or gonorrhea.","Untreated infection ascends as PID and scars the fallopian tubes.","Tubal damage causes infertility, ectopic pregnancy and chronic pelvic pain."]],
  ["OB-043","ASSOCIATION","Breast","Red, scaly, eczema-like nipple rash unresponsive to steroid cream — biopsy shows","Adenocarcinoma cells in epidermis",["Lymphoma cells in dermis","Papillary fibrovascular cores","Malignant vascular channels"],["A unilateral eczematous nipple lesion that persists is Paget disease of the breast.","Large malignant cells with clear halos sit within the epidermis.","It almost always signals underlying ductal carcinoma in situ or invasive cancer."]],
  ["OB-044","ASSOCIATION","Pelvic anatomy","Oophorectomy for a complex ovarian mass — ligament to ligate to avoid bleeding","Suspensory ligament of the ovary",["Round ligament of the uterus","Utero-ovarian ligament","Transverse cervical ligament"],["The suspensory (infundibulopelvic) ligament carries the ovarian artery and vein.","It must be ligated when the ovary is removed.","The ureter runs close to it, so it is at risk during this step."]],
  ["OB-045","ASSOCIATION","Vaginal & pelvic infections","Grey, fishy-smelling discharge with no inflammation — wet mount finding","Epithelial cells coated with bacteria",["Pear-shaped flagellated organisms","Pseudohyphae with white cells","Intracellular diplococci"],["Thin grey discharge with a fishy odour is bacterial vaginosis from Gardnerella overgrowth.","The wet mount shows clue cells, and the whiff test is positive with pH above 4.5.","It is treated with metronidazole or clindamycin."]],
  ["OB-046","ASSOCIATION","Disorders of sex development","Tall 15-year-old with full breasts and pubic hair, no menses, short vagina and rudimentary uterus","Müllerian agenesis",["Androgen insensitivity","Kallmann syndrome","21-hydroxylase deficiency"],["Normal breasts and pubic hair mean functioning ovaries and normal androgen action.","Müllerian agenesis (MRKH) leaves an absent or rudimentary uterus and upper vagina in a 46,XX girl.","Androgen insensitivity would cause sparse pubic hair and a 46,XY karyotype."]],
  ["OB-047","ASSOCIATION","Breast","Mobile 2-cm breast lump in a 34-year-old; biopsy shows ducts compressed by loose stroma","Fibroadenoma",["Medullary carcinoma","Duct ectasia","Ductal carcinoma in situ"],["Fibroadenoma is the most common breast tumor in young women.","It is a well-circumscribed, mobile mass of proliferating stroma compressing ducts into slits.","It may grow with estrogen in pregnancy and is not premalignant."]],
  ["OB-048","ASSOCIATION","Vaginal & pelvic infections","Fever, malaise, inguinal nodes and painful vulvar vesicles after a new partner — later course","Recurrent genital ulcers",["Fluctuant groin lymph nodes","Locomotor ataxia","Squamous vulvar cancer"],["Painful grouped vesicles with systemic symptoms are primary genital herpes (usually HSV-2).","The virus stays latent in the sacral dorsal root ganglia.","It reactivates as recurrent, milder ulcers; acyclovir shortens episodes."]],
  ["OB-049","MECHANISM","Pelvic anatomy","Older woman with COPD and chronic cough leaks urine when coughing — cause","Weak pelvic floor support",["Vesicovaginal fistula","Detrusor overactivity","Overflow from atony"],["Leakage with coughing or straining is stress urinary incontinence.","Weak pelvic floor muscles let the urethra move, so it cannot stay closed when abdominal pressure rises.","Chronic cough, obesity and vaginal births are risk factors; pelvic floor exercises help."]],
  ["OB-050","ASSOCIATION","Ovarian masses","Adnexal mass removed from a 26-year-old shows skin, hair follicles and sebaceous glands","Mature teratoma",["Serous carcinoma","Endometrioma","Ectopic pregnancy"],["A mature cystic teratoma (dermoid) contains tissues from all three germ layers.","It is the most common ovarian germ cell tumor and is usually benign.","Large ones can cause torsion; rarely a squamous carcinoma arises in one."]],
  ["OB-051","ASSOCIATION","Breast","Screening microcalcifications; biopsy shows pleomorphic cells filling ducts without invasion — site of origin","Terminal duct lobular unit",["Large lactiferous ducts","Fibrous breast stroma","Subcutaneous fat"],["Ductal carcinoma in situ fills ducts but does not cross the basement membrane.","Most breast cancers, ductal and lobular, arise in the terminal duct lobular unit.","DCIS often shows as microcalcifications, especially the comedo type with central necrosis."]],
  ["OB-052","ASSOCIATION","Pelvic anatomy","Sudden right pelvic pain while shoveling snow, adnexal tenderness — structure the ovary twists around","Infundibulopelvic ligament",["Cardinal ligament","Round ligament","Uterosacral ligament"],["Ovarian torsion is twisting of the ovary on its vascular pedicle.","The infundibulopelvic ligament carries the ovarian vessels, so twisting cuts off venous return then arterial flow.","The cardinal ligament carries the uterine vessels instead."]],
  ["OB-053","ASSOCIATION","Pelvic anatomy","Perineal tear repair; local anesthetic injected near the ischial spine and sacrospinous ligament — nerve","Pudendal",["Obturator","Genitofemoral","Ilioinguinal"],["The pudendal nerve (S2-S4) passes around the ischial spine and sacrospinous ligament.","Blocking it there numbs the perineum and external genitalia.","Pudendal block is used for vaginal delivery and perineal repair."]],
  ["OB-054","MECHANISM","Cervical disease","Ulcerated cervical lesion with invasive squamous cells and HPV DNA — how the virus causes cancer","Inactivating cell cycle brakes",["Activating growth factor receptors","Inactivating DNA repair enzymes","Activating RAS signal proteins"],["High-risk HPV types 16 and 18 cause cervical squamous cell carcinoma.","Viral E6 degrades p53 and E7 binds and inactivates Rb.","Without these tumor suppressors, infected cells pass checkpoints and divide uncontrollably."]],
  ["OB-055","ASSOCIATION","Uterine disorders","Multiparous 42-year-old with heavy, painful periods and a uniformly enlarged tender uterus — histology","Endometrial tissue in the myometrium",["Smooth muscle tumor in the myometrium","Overgrowth of endometrial glands","Polyp projecting into the cavity"],["Heavy painful periods with a globular, boggy uterus is adenomyosis.","Endometrial glands and stroma are found deep within the myometrium.","Fibroids instead make the uterus irregular and nodular."]],
  ["OB-056","MECHANISM","Disorders of sex development","Newborn girl with a posterior neck cystic hygroma and nonpitting hand and foot edema — genetic cause","Loss of the paternal X",["Maternal trisomy 18","Robertsonian translocation 21","Deletion of 5p"],["Cystic hygroma and lymphedema of the hands and feet in a newborn are classic for Turner syndrome.","They result from abnormal lymphatic development.","The missing sex chromosome is usually the father's."]],
  ["OB-057","ASSOCIATION","Ovarian masses","Older woman with rising abdominal girth, early satiety and a complex adnexal mass — tumor marker","CA-125",["Alpha-fetoprotein","Beta-hCG","Lactate dehydrogenase"],["Epithelial ovarian cancer, usually serous, is the most common ovarian cancer in older women.","It presents late with bloating, ascites and early satiety.","CA-125 is used to monitor response, not to screen the general population."]],
  ["OB-058","ASSOCIATION","Pregnancy complications","Five weeks after her last period: bleeding, cramping, tachycardia, positive hCG and an adnexal mass","Tubal implantation of an embryo",["Fertilisation by two sperm","Endometrium within the ovary","Torsion of a dermoid cyst"],["Pain, bleeding and an adnexal mass with a positive hCG is ectopic pregnancy until proven otherwise.","Most ectopics implant in the ampulla of the fallopian tube.","Risk factors are prior PID, tubal surgery and a previous ectopic."]],
  ["OB-059","ASSOCIATION","Pelvic anatomy","Second-degree tear at the posterior vaginal opening after delivery — structure damaged","Perineal body",["Internal anal sphincter","Ischiocavernosus","Sacrotuberous ligament"],["The perineal body is the fibromuscular centre point between the vagina and anus.","Second-degree tears go through the vaginal mucosa into the perineal muscles at this point.","Third- and fourth-degree tears reach the anal sphincter and rectal mucosa."]],
  ["OB-060","ASSOCIATION","Ovarian masses","Ovarian torsion after exercise; the removed cyst contains hair and yellow greasy material","Mature cystic teratoma",["Endometrioma","Mucinous cystadenoma","Ovarian fibroma"],["Hair, sebum and teeth inside an ovarian cyst mean a dermoid cyst.","Dermoids are the most common ovarian masses to cause torsion.","Endometriomas contain dark chocolate-like old blood instead."]],
  ["OB-061","ASSOCIATION","Cervical disease","Two abnormal Pap tests; biopsy reports high-grade CIN — microscopic finding","Atypia above the lower third",["Atypia in the lower third only","Invasion beyond the basement","Clear perinuclear halos alone"],["CIN is graded by how far atypical basal cells extend toward the surface.","CIN 1 affects the lower third, while high-grade CIN 2-3 extends beyond it, up to full thickness.","Clear perinuclear halos (koilocytes) mark HPV infection, and invasion means carcinoma."]],
  ["OB-062","ASSOCIATION","Breast","Bilateral milky nipple discharge, amenorrhea for 6 months and infertility","Pituitary adenoma",["Fibroadenoma","Galactocele","Fibrocystic change"],["Galactorrhea with amenorrhea and infertility suggests a prolactinoma.","Prolactin suppresses hypothalamic GnRH, so FSH, LH and estrogen fall.","Dopamine agonists such as cabergoline lower prolactin and restore ovulation."]],
  ["OB-063","MECHANISM","Infertility & PCOS","Obese woman with PCOS and anovulatory infertility starts letrozole — how it induces ovulation","Blocks ovarian estrogen synthesis",["Activates pituitary dopamine receptors","Stimulates growth of the endometrium","Inhibits gonadotropin secretion"],["Letrozole is an aromatase inhibitor and is first-line for ovulation induction in PCOS.","Lower estrogen removes negative feedback, so the pituitary releases more FSH.","The extra FSH drives follicle growth and ovulation."]],
  ["OB-064","ASSOCIATION","Ovarian masses","Weight loss, epigastric pain and early satiety, with a thick gastric wall and bilateral ovarian masses — histology","Mucin-filled signet ring cells",["Keratin pearls and bridges","Sebaceous glands and keratin","Nests of clear cells"],["Bilateral ovarian metastases from gastric cancer are Krukenberg tumors.","Diffuse gastric adenocarcinoma shows signet ring cells with mucin pushing the nucleus aside.","Bilateral ovarian masses should prompt a search for a GI primary."]],
  ["OB-065","MECHANISM","Disorders of sex development","Four consecutive miscarriages; hysterosalpingogram shows two separate uterine horns","Failed fusion of paramesonephric ducts",["Failed development of paramesonephric ducts","Failed fusion of mesonephric ducts","Failed fusion with the urogenital sinus"],["A bicornuate uterus results from incomplete lateral fusion of the two paramesonephric (Müllerian) ducts.","Failed resorption of the septum after fusion causes a septate uterus instead.","Uterine anomalies cause recurrent pregnancy loss and malpresentation."]],
  ["OB-066","ASSOCIATION","Sexual health","Woman with low sexual interest and distracted thoughts but normal arousal and orgasm, for a year","Sexual interest/arousal disorder",["Female orgasmic disorder","Adjustment disorder","Genito-pelvic pain disorder"],["Persistent low interest or arousal for at least 6 months that causes distress defines this disorder.","Lubrication and orgasm can be normal.","Medical causes, drugs such as SSRIs and relationship problems should be looked for first."]],
  ["OB-067","MECHANISM","Contraception & drugs","Woman switching from a progestin-only pill to a combined pill — main contraceptive action","Suppressed gonadotropin release",["Thicker cervical mucus","Impaired implantation","Lower SHBG levels"],["Estrogen and progestin feed back on the hypothalamus and pituitary.","Lower FSH and LH mean no follicle development and no LH surge, so ovulation stops.","Progestin-only pills rely more on thickening cervical mucus."]],
  ["OB-068","ASSOCIATION","Breast","Bloody discharge from one nipple, no mass — histology of the lesion","Epithelium over fibrovascular cores",["Apocrine metaplastic cysts","Fat necrosis with inflammation","Malignant cells in the nipple"],["Bloody nipple discharge without a mass in a young woman is usually an intraductal papilloma.","It arises in a large lactiferous duct beneath the areola.","It is benign but is excised to exclude papillary carcinoma."]],
  ["OB-069","ASSOCIATION","Menstrual cycle & hormones","Endometrial biopsy shows coiled glands with secretions, edematous stroma and spiral arteries — cycle phase","Mid luteal phase",["Early follicular phase","Mid follicular phase","Midcycle LH peak"],["The secretory endometrium is shaped by progesterone from the corpus luteum.","Tortuous glands with secretions, stromal edema and spiral arteries are mid-secretory changes.","The proliferative phase has straight tubular glands driven by estrogen."]],
  ["OB-070","ASSOCIATION","Infertility & PCOS","Woman with Turner syndrome asks how she could become pregnant","IVF with a donor egg",["Clomiphene citrate","Pulsatile GnRH","Bromocriptine"],["Turner syndrome causes streak ovaries with no functioning follicles.","Drugs that stimulate the ovary cannot work without oocytes.","Pregnancy is possible with a donor oocyte, after cardiac assessment for aortic risk."]],
  ["OB-071","ASSOCIATION","Vaginal & pelvic infections","Vulvar itching with thick discharge; wet mount shows branching pseudohyphae — treatment","Fluconazole",["Metronidazole","Clindamycin","Acyclovir"],["Pseudohyphae on KOH or wet mount mean vulvovaginal candidiasis.","The vaginal pH stays normal (4 to 4.5).","A single oral dose of fluconazole or a topical azole treats it."]],
  ["OB-072","MECHANISM","Infertility & PCOS","PCOS treated with ovulation induction, then an hCG injection — hormone it imitates","LH",["FSH","Estrogen","Progesterone"],["hCG and LH share an alpha subunit and bind the same receptor.","An hCG trigger mimics the midcycle LH surge.","This causes final oocyte maturation and ovulation about 36 hours later."]],
  ["OB-073","ASSOCIATION","Disorders of sex development","15-year-old with normal breasts, no periods and monthly worsening cyclic pelvic pain","Imperforate hymen",["Androgen insensitivity","Asherman syndrome","Kallmann syndrome"],["Normal puberty with cyclic pain and no bleeding means an outflow obstruction.","Menstrual blood collects behind an imperforate hymen (hematocolpos), which may bulge blue.","Treatment is surgical opening of the hymen."]],
  ["OB-074","ASSOCIATION","Uterine disorders","Painful urination and defecation that worsen with periods, fixed retroverted uterus, uterosacral nodules — biopsy","Endometrial glands and stroma",["Invasive urothelial carcinoma","Serous ovarian carcinoma","Colorectal hamartoma"],["Endometriosis is functional endometrial tissue outside the uterus.","Implants on the bladder and rectovaginal septum cause cyclic dysuria and dyschezia.","Scarring fixes the uterus in retroversion and causes nodularity of the uterosacral ligaments."]],
  ["OB-075","ASSOCIATION","Contraception & drugs","Woman wanting contraception has migraines with visual aura — what rules out combined pills","Her type of headache",["Her body mass index","Her prior abnormal Pap","Her menstrual pattern"],["Migraine with aura already raises the risk of ischemic stroke.","Estrogen raises that risk further, so estrogen-containing methods are contraindicated.","An IUD, implant or progestin-only method is safer."]],
  ["OB-076","MECHANISM","Contraception & drugs","Woman with fibroids on continuous leuprolide for 3 months — hormone pattern","Low GnRH, FSH and estrogen",["High GnRH, FSH and estrogen","High GnRH, low FSH and estrogen","Low GnRH and FSH, high estrogen"],["Continuous GnRH agonist exposure downregulates pituitary GnRH receptors.","FSH and LH fall, so the ovaries stop making estrogen, and hypothalamic GnRH also falls.","Low estrogen shrinks fibroids before surgery but causes hot flashes and bone loss."]],
  ["OB-077","MECHANISM","Pregnancy physiology","Near term, estrogen induces oxytocin receptors and connexin 43 in myometrium — structures that increase","Gap junctions",["Desmosomes","Adherens junctions","Hemidesmosomes"],["Connexin 43 is the protein that forms gap junctions.","More gap junctions let calcium and electrical signals pass between myometrial cells.","The uterus then contracts as one coordinated unit during labor."]],
  ["OB-078","ASSOCIATION","Disorders of sex development","17-year-old dies of aortic dissection; autopsy shows a small uterus and streak ovaries — other finding","Horseshoe kidney",["Lens dislocation","Mitral valve prolapse","Wilms tumor"],["Streak ovaries with aortic disease mean Turner syndrome.","Bicuspid aortic valve, coarctation and dissection are its main cardiac risks.","A horseshoe kidney, fused at the lower poles, is the classic renal finding."]],
  ["OB-079","MECHANISM","Menstrual cycle & hormones","14-year-old a year after menarche with irregular, heavy, prolonged periods — cause","Immature GnRH pulsatility",["High serum LH levels","Excess FSH secretion","Estrogen made in body fat"],["For the first years after menarche the hypothalamic-pituitary axis is immature.","GnRH pulses are irregular, so there is no LH surge and no ovulation.","Without progesterone the endometrium grows unopposed and sheds heavily and irregularly."]],
  ["OB-080","ASSOCIATION","Infertility & PCOS","Obese woman with periods every 2–3 months, acne and chin hair — pathologic finding","Enlarged cystic ovaries",["Atrophic endometrium","Bilateral adrenal atrophy","Pituitary adenoma"],["PCOS is anovulation plus hyperandrogenism, with or without polycystic ovaries.","The ovaries are enlarged with many small peripheral follicles and thick theca.","High LH relative to FSH drives theca cells to make excess androgen."]],
  ["OB-081","ASSOCIATION","Urinary tract infection","Woman with urinary frequency and urgency — finding that places the infection in the kidney","White blood cell casts",["Bacteria in the urine","Microscopic hematuria","Raised blood white count"],["Casts form only in renal tubules.","White cell casts in a urinary infection mean pyelonephritis rather than cystitis.","Pyelonephritis also causes fever, flank pain and costovertebral angle tenderness."]],
  ["OB-082","MECHANISM","Breast","Older woman with a fixed upper outer breast mass and puckered overlying skin — structure invaded","Suspensory ligaments",["Lactiferous ducts","Axillary nodes","Nipple"],["Cooper (suspensory) ligaments run from the deep fascia to the skin.","Cancer infiltrating and shortening them pulls the skin inward, causing dimpling.","Nipple retraction instead reflects involvement of the lactiferous ducts."]],
  ["OB-083","ASSOCIATION","Pelvic anatomy","Fever and right flank pain 8 days postpartum from a right ovarian vein clot — where it can extend","Inferior vena cava",["Right renal vein","Right internal iliac vein","Right common iliac vein"],["Septic pelvic thrombophlebitis typically involves the right ovarian vein after delivery.","The right ovarian vein drains directly into the IVC, while the left drains into the left renal vein.","It persists despite antibiotics and is treated with anticoagulation."]],
  ["OB-084","ASSOCIATION","Pregnancy complications","12-week pregnancy with bleeding, hyperemesis and a uterus large for dates — karyotype of the tissue","46,XX",["69,XXX","47,XXY","46,XY"],["A uterus large for dates with severe vomiting and bleeding suggests a complete mole.","A complete mole is usually 46,XX, from an empty egg fertilised by one sperm that duplicates.","There is no fetal tissue, hCG is very high, and the risk of choriocarcinoma is raised."]],
  ["OB-085","ASSOCIATION","Vaginal & pelvic infections","Frothy yellow-green discharge with dysuria and an inflamed cervix — confirming test","Saline wet mount",["KOH whiff test","Gram stain","Cervical cytology"],["Frothy green discharge with a strawberry cervix is trichomoniasis.","Saline wet mount shows motile flagellated trophozoites, though NAAT is more sensitive.","Treat both partners with metronidazole."]],
  ["OB-086","ASSOCIATION","Ovarian masses","Postmenopausal woman with ascites, weight loss and an ovarian mass — what would have lowered her risk","Oral contraceptive use",["HPV vaccination","Consistent condom use","Antioxidant supplements"],["Epithelial ovarian cancer risk rises with the lifetime number of ovulations.","Combined oral contraceptives, pregnancy and breastfeeding all suppress ovulation and lower the risk.","BRCA mutations and nulliparity raise it."]],
  ["OB-087","ASSOCIATION","Uterine disorders","Regular heavy painful periods; hysterectomy shows a globular uterus with dark spots in the muscle","Adenomyosis",["Leiomyoma","Endometriosis","Chronic endometritis"],["Adenomyosis is endometrium within the myometrium, causing a uniformly enlarged, globular uterus.","Dark hemorrhagic spots in the muscle are the trapped glands bleeding each cycle.","It is most common in multiparous women in their 40s; hysterectomy is curative."]],
  ["OB-088","ASSOCIATION","Cervical disease","Routine Pap: squamous cells with a clear halo around a large, dark, wrinkled nucleus","Koilocytes",["Clue cells","Parabasal cells","Endocervical cells"],["Koilocytes are the cytopathic effect of HPV infection.","They show a raisinoid nucleus surrounded by a clear perinuclear halo.","Clue cells, by contrast, are epithelial cells coated with bacteria in bacterial vaginosis."]],
  ["OB-089","ASSOCIATION","Disorders of sex development","Short 15-year-old with no breasts, a high-arched palate and widely spaced nipples — gonadal finding","Streak ovaries",["Absent uterus","Fibrosed fallopian tubes","Ambiguous genitalia"],["This is Turner syndrome (45,X).","Oocytes are lost early, leaving fibrous streak gonads that make no estrogen.","FSH and LH are high (hypergonadotropic hypogonadism), but the uterus and tubes are normal."]],
  ["OB-090","MECHANISM","Urinary tract infection","Young woman with recurrent cystitis now recovering from pyelonephritis — how bacteria reached the kidney","Retrograde urine flow",["Spread through the blood","Suppression of normal flora","Colonisation of the urethra"],["Most pyelonephritis is an ascending infection from the bladder.","Inflammation can make the vesicoureteral junction incompetent, so urine refluxes up the ureter.","Hematogenous spread to the kidney is uncommon and usually involves S. aureus."]],
  ["OB-091","MECHANISM","Uterine disorders","Obese diabetic woman with postmenopausal bleeding — source of the estrogen driving her endometrium","Aromatisation of androgens in fat",["Autonomous pituitary prolactin","Ectopic endometrial tissue","Raised binding globulin"],["Postmenopausal bleeding needs evaluation for endometrial hyperplasia or carcinoma.","After menopause, adipose aromatase converts androstenedione to estrone.","This unopposed estrogen drives type 1 (endometrioid) endometrial cancer."]],
  ["OB-092","ASSOCIATION","Pelvic anatomy","Smoker with squamous cell carcinoma of the labia majora — sentinel node group","Inguinofemoral",["External iliac","Para-aortic","Obturator"],["The vulva drains first to the superficial inguinal (inguinofemoral) nodes.","These are sampled by sentinel node biopsy in vulvar cancer.","The ovaries and testes drain instead to the para-aortic nodes."]],
  ["OB-093","MECHANISM","Urinary tract infection","16-year-old with dysuria and suprapubic tenderness a week after sex — route of infection","Ascending from the urethra",["Blood-borne spread","Lymphatic spread","Sexual transmission"],["Acute cystitis follows colonisation of the periurethral area by gut flora.","Bacteria then ascend the short female urethra into the bladder.","Intercourse pushes bacteria toward the urethra, which is why it is a risk factor."]],
  ["OB-094","ASSOCIATION","Urinary tract infection","Young man with dysuria, no discharge, nitrite-positive acidic urine — organism","Escherichia coli",["Proteus mirabilis","Enterococcus faecalis","Candida albicans"],["E. coli is the most common cause of UTI in men and women.","Gram-negative rods reduce urinary nitrate to nitrite, so the nitrite test is positive.","Proteus makes urease and alkaline urine, and Enterococcus does not make nitrite."]],
  ["OB-095","ASSOCIATION","Pregnancy complications","Ruptured ectopic pregnancy in a woman with one partner — organism behind most tubal scarring","Neisseria gonorrhoeae",["Gardnerella vaginalis","Human papillomavirus","Escherichia coli"],["The main risk factor for ectopic pregnancy is tubal damage from prior PID.","PID is caused mainly by N. gonorrhoeae and C. trachomatis.","Scarred tubes slow the embryo, so it implants in the tube."]],
  ["OB-096","ASSOCIATION","Uterine disorders","Laparoscopy for endometriosis; biopsy of a nodule shows simple cuboidal surface epithelium — organ","Ovary",["Cervix","Fallopian tube","Vagina"],["The ovarian surface is covered by a single layer of cuboidal (germinal) epithelium.","The ovary is the most common site of endometriosis.","Ovarian implants can form endometriomas full of old blood (chocolate cysts)."]],
  ["OB-097","ASSOCIATION","Uterine disorders","Woman on tamoxifen with daily bleeding and a growing uterine mass; myometrium shows atypia and many mitoses","Uterine sarcoma",["Uterine fibroid","Adenomyosis","Endometritis"],["A rapidly enlarging uterine mass near menopause raises concern for leiomyosarcoma.","Malignancy is defined by nuclear atypia, high mitotic activity and necrosis.","Tamoxifen acts as an estrogen agonist on the uterus and raises the risk of endometrial cancer and sarcoma."]],
  ["OB-098","ASSOCIATION","Vaginal & pelvic infections","IUD user with a new partner; discharge cytology shows clue cells — main organism","Anaerobic gram-variable rod",["Gram-negative diplococcus","Motile flagellated protozoan","Dimorphic budding fungus"],["Clue cells are diagnostic of bacterial vaginosis.","Gardnerella vaginalis is a gram-variable rod that overgrows with anaerobes when lactobacilli fall.","It is not a classic STI but is linked to new partners and IUD use."]],
  ["OB-099","ASSOCIATION","Uterine disorders","Infertility, painful periods, deep dyspareunia and a tender posterior fornix","Endometrium outside the uterus",["Endometrium inside the myometrium","Glands crowding out the stroma","Cystic ovaries with thick cortex"],["This triad (dysmenorrhea, dyspareunia, infertility) is endometriosis.","Implants on the uterosacral ligaments and cul-de-sac cause pain with deep penetration.","Retrograde menstruation is the leading theory for how tissue reaches the pelvis."]],
  ["OB-100","ASSOCIATION","Ovarian masses","Weight loss, hot flashes, low TSH and an oily adnexal cyst — cell of origin","Germ cells",["Granulosa cells","Theca cells","Ovarian fibroblasts"],["Struma ovarii is a teratoma made mostly of thyroid tissue.","It can secrete thyroid hormone and cause hyperthyroidism with a suppressed TSH.","Teratomas arise from germ cells, which is why they contain several tissue types."]],
  ["OB-101","MECHANISM","Pelvic anatomy","Older woman after two forceps deliveries strains to pass stool; posterior vaginal bulge on straining","Levator ani damage",["Absent colonic ganglia","External sphincter defect","High internal sphincter tone"],["The bulge is a rectocele, where the rectum herniates into the posterior vaginal wall.","Operative vaginal births stretch and tear the levator ani and its fascia.","Stool collects in the pouch, so patients may need to press on the vagina to defecate."]],
  ["OB-102","ASSOCIATION","Pregnancy complications","Adnexal mass removed for pain and bleeding; specimen shows an embryo inside the tube — risk factor","Prior pelvic surgery",["Recent anticoagulant use","Progestin-only pill use","Family ovarian cancer"],["An embryo in the fallopian tube is an ectopic pregnancy.","Pelvic surgery, PID and prior ectopic pregnancy all scar the tubes.","Scarring delays transport of the embryo, so it implants before reaching the uterus."]],
  ["OB-103","ASSOCIATION","Uterine disorders","Heavy periods with clots and a sharply outlined round mass in the uterine wall — histology","Monoclonal smooth muscle whorls",["Atypical squamous cells","Crowded endometrial glands","Glands with hemosiderin"],["A well-circumscribed myometrial mass with heavy bleeding is a leiomyoma (fibroid).","Fibroids are benign monoclonal proliferations of smooth muscle cells in whorled bundles.","They are estrogen-sensitive, grow in pregnancy and shrink after menopause."]],
  ["OB-104","ASSOCIATION","Pelvic anatomy","Back pain after hysterectomy for a low fibroid near the cardinal ligament — structure injured","Ureter",["Bladder","Ovarian artery","External iliac artery"],["The ureter passes under the uterine artery in the cardinal ligament (water under the bridge).","Clamping or suturing the uterine artery there can catch the ureter.","A blocked ureter causes flank pain and hydronephrosis on that side."]],
  ["OB-105","ASSOCIATION","Pregnancy complications","Low, slowly rising hCG and no intrauterine sac — endometrial curettage shows","Decidualised endometrium, no villi",["Disorganised atypical glands","Short straight proliferative glands","Glands infiltrated by plasma cells"],["A low, plateauing hCG with an empty uterus suggests an ectopic pregnancy.","The endometrium still responds to pregnancy hormones with decidual change.","Absence of chorionic villi in the curettings supports an ectopic location."]],
  ["OB-106","MECHANISM","Pregnancy complications","35 weeks pregnant with very high BP, occipital headache and bilateral blind spots — cause of the visual loss","Retinal artery vasospasm",["Vitreous hemorrhage","Optic nerve demyelination","Angle-closure glaucoma"],["Visual scotomas and headache with severe hypertension are features of preeclampsia with severe features.","Endothelial dysfunction causes spasm of the cerebral and retinal arteries.","Treatment is magnesium sulfate, blood pressure control and delivery."]],
  ["OB-107","ASSOCIATION","Embryology & fertilisation","Positive test 5 weeks after a single act of intercourse — event happening in the embryo now","Neural crest migration",["Blastocyst implantation","Gastrulation","Alveolar formation"],["Embryonic age counts from fertilisation, two weeks less than gestational age from the last period.","Implantation happens in week 1 and gastrulation in week 3.","By weeks 4 to 5 the neural tube has closed and neural crest cells are migrating."]],
  ["OB-108","ASSOCIATION","Teratogens & congenital infection","Breech baby from a fibroid uterus has clubfeet that can be moved back to normal — type of defect","Deformation",["Malformation","Disruption","Sequence"],["A deformation is a normal structure shaped abnormally by outside mechanical force.","Crowding from breech position, fibroids or oligohydramnios causes them, usually late in pregnancy.","A malformation is an intrinsic error in development, and a disruption destroys normal tissue."]],
  ["OB-109","ASSOCIATION","Teratogens & congenital infection","28 weeks, uterus large for dates with polyhydramnios; mother takes antiepileptics and had no care — fetal finding","Anencephaly",["Renal agenesis","Pulmonary hypoplasia","Posterior urethral valves"],["Valproate and carbamazepine interfere with folate and cause neural tube defects.","An anencephalic fetus cannot swallow amniotic fluid, so polyhydramnios develops.","Renal agenesis and urethral valves cause oligohydramnios instead."]],
  ["OB-110","ASSOCIATION","Teratogens & congenital infection","3-week-old with a firm lateral neck lump and a head that tilts and prefers one side — cause","Malposition in the uterus",["Maternal folate deficiency","Defective fetal collagen","Maternal alcohol use"],["Congenital muscular torticollis is a shortened, fibrotic sternocleidomastoid.","It is usually caused by intrauterine crowding or birth trauma.","Most cases resolve with stretching exercises."]],
  ["OB-111","MECHANISM","Contraception & drugs","First-trimester termination with mifepristone followed by misoprostol — mifepristone action","Progesterone receptor antagonist",["Prostaglandin E1 analog","Oxytocin receptor agonist","Folate antagonist"],["Progesterone maintains the decidua in early pregnancy.","Mifepristone blocks its receptor, so the decidua breaks down and the cervix softens.","Misoprostol, a PGE1 analog, then causes uterine contractions to expel the tissue."]],
  ["OB-112","ASSOCIATION","Teratogens & congenital infection","Unvaccinated woman with fever, arthralgia, postauricular nodes and a rash spreading head to toe in early pregnancy","Microcephaly and hearing loss",["Hydrocephalus and chorioretinitis","Vesicles and keratitis","Notched teeth and meningitis"],["This is maternal rubella in the first trimester.","Congenital rubella causes sensorineural deafness, cataracts and PDA, with microcephaly.","Hydrocephalus with chorioretinitis is toxoplasmosis, and vesicles with keratitis is HSV."]],
  ["OB-113","ASSOCIATION","Pregnancy physiology","34 weeks pregnant with pain over the front of the pelvis — hormone behind it","Relaxin",["Oxytocin","Human chorionic gonadotropin","Growth hormone"],["Relaxin from the corpus luteum and placenta remodels connective tissue in pregnancy.","It loosens the pelvic ligaments and widens the pubic symphysis to prepare for birth.","This can cause symphyseal pain, which is usually benign."]],
  ["OB-114","ASSOCIATION","Pregnancy complications","Bleeding at 12 weeks; tissue shows fetal parts with a mix of swollen and normal villi and focal trophoblast overgrowth","Partial mole",["Complete mole","Invasive mole","Choriocarcinoma"],["A partial mole has fetal tissue and patchy villous swelling.","It is triploid (69,XXX or 69,XXY), from one egg fertilised by two sperm.","A complete mole has no fetal parts, diffuse swelling and a higher risk of choriocarcinoma."]],
  ["OB-115","ASSOCIATION","Pregnancy complications","18 weeks after three cesareans, anterior placenta invading the old scar — organ at risk","Bladder",["Cervix","Broad ligament","Uterosacral ligament"],["Prior cesareans with an anterior low placenta is the main setting for placenta accreta spectrum.","In percreta the villi pass through the uterine wall.","The bladder lies directly in front of the lower uterus, so it is the organ most often invaded."]],
  ["OB-116","MECHANISM","Pregnancy physiology","36 weeks pregnant: normal BP sitting and standing but 80/60 and nausea lying on her back","Reduced venous return",["Volume depletion","Increased vagal tone","Low arterial resistance"],["In late pregnancy the uterus compresses the inferior vena cava when the woman lies supine.","Less blood returns to the heart, so cardiac output and blood pressure fall.","Lying on the left side relieves supine hypotensive syndrome."]],
  ["OB-117","ASSOCIATION","Embryology & fertilisation","Couple timing intercourse with an ovulation kit — earliest serum hCG detection after fertilisation","8 days",["1 day","3 days","14 days"],["The blastocyst implants about 6 days after fertilisation.","Syncytiotrophoblast then starts to secrete hCG into maternal blood.","Serum hCG becomes detectable around 8 days after fertilisation, before the missed period."]],
  ["OB-118","ASSOCIATION","Pregnancy complications","Prior cesarean, placenta removed only in pieces, heavy bleeding despite a firm uterus","Placenta invading the myometrium",["Full-thickness uterine rupture","Hypertensive placental detachment","Poor myometrial contraction"],["A placenta that will not separate cleanly after a prior cesarean suggests placenta accreta spectrum.","The villi attach to or invade the myometrium because the decidua basalis is deficient.","A firm uterus argues against atony; hysterectomy is often required."]],
  ["OB-119","ASSOCIATION","Teratogens & congenital infection","Boy with an apically displaced tricuspid valve and an atrialised right ventricle — maternal condition","Bipolar disorder",["Epilepsy","Alcohol use disorder","Cocaine use"],["Downward displacement of the tricuspid leaflets is Ebstein anomaly.","It is linked to maternal lithium use in the first trimester.","Lithium is the classic mood stabiliser for bipolar disorder."]],
  ["OB-120","ASSOCIATION","Pregnancy complications","Newborn after vacuum delivery with a soft scalp swelling crossing sutures into the neck — space of bleeding","Between periosteum and galea",["Between dura and periosteum","Between arachnoid and dura","Between skull and periosteum"],["Subgaleal hemorrhage lies under the galea aponeurosis, above the periosteum.","The space is large and not limited by sutures, so a newborn can lose much of its blood volume.","Cephalohematoma lies under the periosteum and stops at suture lines."]],
  ["OB-121","MECHANISM","Pregnancy physiology","28 weeks pregnant, obese, leaks urine only when coughing","Raised intra-abdominal pressure",["Detrusor overactivity","Bladder outlet obstruction","Weak detrusor contraction"],["Leakage with coughing or sneezing is stress incontinence.","Sudden rises in abdominal pressure overcome a weakened urethral closure mechanism.","The gravid uterus, obesity and prior vaginal birth all add to the pressure and laxity."]],
  ["OB-122","ASSOCIATION","Teratogens & congenital infection","Small newborn with bilateral cataracts, a continuous machine-like murmur and hearing loss — how it could have been prevented","Live vaccine before conception",["Killed vaccine in pregnancy","Antibiotics around delivery","Antiviral in third trimester"],["Cataracts, PDA and deafness are the triad of congenital rubella syndrome.","The MMR vaccine prevents it but is live, so it is given before pregnancy.","Women should avoid pregnancy for 4 weeks after MMR; if non-immune in pregnancy, vaccinate postpartum."]],
  ["OB-123","ASSOCIATION","Embryology & fertilisation","At ovulation, just before fertilisation — stage where the oocyte is arrested","Metaphase II",["Prophase I","Metaphase I","Telophase I"],["Primary oocytes are arrested in prophase I from fetal life until puberty.","Just before ovulation they complete meiosis I and arrest again in metaphase II.","Meiosis II finishes only when a sperm fertilises the egg."]],
  ["OB-124","MECHANISM","Pregnancy physiology","16 weeks pregnant with trace protein on dipstick, normal BP and normal labs — cause","Increased GFR",["Podocyte foot process effacement","Mesangial matrix expansion","Widespread endothelial injury"],["GFR rises by about 50% in pregnancy as renal plasma flow increases.","More filtered protein reaches the tubules, so mild proteinuria under 300 mg a day is normal.","Creatinine falls in pregnancy, so a normal-range value may actually be high."]],
  ["OB-125","MECHANISM","Pregnancy physiology","Abnormal 50-g glucose screen at 28 weeks — placental hormone driving insulin resistance","Human placental lactogen",["Human chorionic gonadotropin","Growth hormone","Prolactin"],["Human placental lactogen rises through the second and third trimesters.","It causes maternal insulin resistance and lipolysis, sparing glucose for the fetus.","If the pancreas cannot compensate, gestational diabetes develops."]],
  ["OB-126","ASSOCIATION","Pregnancy physiology","Healthy woman at 28 weeks with a soft systolic murmur at the left sternal border that rises with inspiration","Flow across the pulmonic valve",["Vegetations on the mitral valve","Calcified bicuspid aortic valve","Myxomatous mitral leaflets"],["Blood volume and cardiac output rise by 30 to 50% in pregnancy.","Higher flow across the pulmonic valve causes a soft benign systolic murmur.","Diastolic murmurs in pregnancy are never normal and need evaluation."]],
  ["OB-127","MECHANISM","Teratogens & congenital infection","Preterm newborn with pulmonary hypoplasia, limb contractures and a poorly ossified skull; mother on antihypertensives","Blocked angiotensin I conversion",["Beta-adrenergic blockade","Alpha-2 adrenergic agonism","Free radical tissue damage"],["ACE inhibitors and ARBs are contraindicated in pregnancy.","They impair fetal renal perfusion, causing renal dysgenesis and oligohydramnios.","Low amniotic fluid then causes pulmonary hypoplasia, contractures and skull hypoplasia."]],
  ["OB-128","ASSOCIATION","Pregnancy physiology","34 weeks pregnant with dependent edema, normal heart and BP — the value that falls in pregnancy","Systemic vascular resistance",["Plasma volume","Cardiac output","Cardiac preload"],["Progesterone and nitric oxide relax vascular smooth muscle in pregnancy.","Systemic vascular resistance falls, so blood pressure drops in the second trimester.","Cardiac output, plasma volume and preload all rise."]],
  ["OB-129","ASSOCIATION","Teratogens & congenital infection","3-week-old born at home, no newborn injections, now drowsy with a large head — cause of intracranial bleeding","Vitamin deficiency",["Inherited hemophilia","Birth trauma","Germinal matrix fragility"],["Newborns have little vitamin K because it crosses the placenta poorly and the gut is sterile.","Breast milk is low in vitamin K, so factors II, VII, IX and X fall.","Late vitamin K deficiency bleeding often causes intracranial hemorrhage; a single IM dose at birth prevents it."]],
  ["OB-130","ASSOCIATION","Pregnancy physiology","Healthy pregnancy at 18 weeks — expected change in coagulation","Hypercoagulable state",["Hypocoagulable state","Unchanged clotting balance","Raised fibrinolysis only"],["Pregnancy raises fibrinogen and factors VII, VIII and X.","Protein S falls and fibrinolysis is suppressed.","This protects against hemorrhage at delivery but raises the risk of venous thromboembolism."]],
  ["OB-131","MECHANISM","Pregnancy complications","Placenta will not separate at cesarean in a woman with a prior cesarean — underlying defect","Missing decidua basalis",["Excess trophoblast growth","Absent Wharton jelly","Neutrophils in the cord"],["Placenta accreta occurs when villi attach directly to the myometrium.","A cesarean scar leaves the decidua basalis deficient at that site.","Placenta previa plus prior cesarean is the strongest risk combination."]],
  ["OB-132","MECHANISM","Pregnancy complications","Large baby of a mother with poorly controlled diabetes becomes hypoglycemic within an hour of birth","Fetal hyperinsulinemia",["Excess maternal insulin","Fetal cortisol deficiency","Low fetal IGF-2"],["Maternal hyperglycemia crosses the placenta, but maternal insulin does not.","The fetal pancreas responds with beta-cell hyperplasia and high insulin, causing macrosomia.","At birth the glucose supply stops but insulin stays high, so glucose falls."]],
  ["OB-133","ASSOCIATION","Teratogens & congenital infection","Quad screen: AFP low, estriol low, hCG high, inhibin A high","Trisomy 21",["Trisomy 18","Neural tube defect","Twin gestation"],["Down syndrome gives low AFP and estriol with high hCG and inhibin A (HI).","Trisomy 18 lowers all markers, with inhibin normal.","A raised AFP points to neural tube or abdominal wall defects or multiple gestation."]],
  ["OB-134","ASSOCIATION","Embryology & fertilisation","Process immediately before hCG first enters the mother's blood","Syncytiotrophoblast invasion",["Morula formation","Zygote formation","Cytotrophoblast formation"],["hCG is made by the syncytiotrophoblast.","It reaches maternal blood once the syncytiotrophoblast invades the endometrium at implantation.","Implantation occurs about 6 days after fertilisation."]],
  ["OB-135","ASSOCIATION","Teratogens & congenital infection","Newborn with Down syndrome features; 26-year-old mother has had repeated miscarriages — karyotype","46,XX,t(14;21)",["47,XX,+18","45,X","46,XX,del(22q11)"],["About 4% of Down syndrome is from an unbalanced Robertsonian translocation.","A parent with a balanced translocation has recurrent miscarriages and a high recurrence risk.","Nondisjunction, the usual cause, is linked to older maternal age."]],
  ["OB-136","ASSOCIATION","Pregnancy complications","Missed period, right-sided pain, spotting, then fainting with hypotension and tachycardia","Ruptured ectopic pregnancy",["Ovarian torsion","Acute appendicitis","Tubo-ovarian abscess"],["Hemodynamic instability with a missed period and pain means intra-abdominal bleeding.","A ruptured ectopic pregnancy is a surgical emergency.","Peritoneal blood irritates the diaphragm and can cause shoulder pain."]],
  ["OB-137","MECHANISM","Contraception & drugs","Stable unruptured ectopic pregnancy in a woman with past chlamydia — mechanism of the drug used","Blocks DNA synthesis in dividing cells",["Blocks progesterone receptors","Triggers prostaglandin contractions","Suppresses LH release"],["Methotrexate is the medical treatment for a stable, unruptured ectopic pregnancy.","It inhibits dihydrofolate reductase, stopping DNA synthesis in rapidly dividing trophoblast.","hCG is followed until it falls to zero."]],
  ["OB-138","MECHANISM","Pregnancy complications","Collapse at cesarean: hypoxia, shock, high CVP with low wedge pressure, then bleeding everywhere","Raised pulmonary vascular resistance",["Reduced right ventricular preload","Raised left atrial pressure","Raised cardiac index"],["Amniotic fluid embolism presents with sudden hypoxia, shock and DIC at delivery.","Fetal material in the pulmonary circulation causes intense vasoconstriction and right heart failure.","Pressure backs up into the right heart, so CVP is high while the wedge pressure is low."]],
  ["OB-139","ASSOCIATION","Pregnancy complications","Fever, hypotension, tender uterus and open cervix 2 days after a surgical termination — common organism","Staphylococcus aureus",["Listeria monocytogenes","Actinomyces species","Chlamydia trachomatis"],["Infection of retained products after abortion is septic abortion.","It is polymicrobial, with S. aureus, gram-negative rods and group B strep common.","Treatment is broad-spectrum antibiotics and urgent uterine evacuation."]],
  ["OB-140","ASSOCIATION","Teratogens & congenital infection","Nodulocystic acne failing antibiotics — test required before starting the next drug","Urine beta-hCG",["Bone density scan","Pelvic ultrasound","Serum retinol"],["Isotretinoin is used for severe nodulocystic acne.","It is a potent teratogen, causing craniofacial, cardiac and CNS defects.","Two negative pregnancy tests and two forms of contraception are needed before starting."]],
  ["OB-141","ASSOCIATION","Pregnancy complications","32 weeks, new BP 165/100, headache, rapid weight gain and edema — urinalysis","Concentrated, with protein",["Dilute, with no protein","Dilute, with protein","Concentrated, with red cells"],["New hypertension after 20 weeks with headache is preeclampsia.","Glomerular endotheliosis lets protein leak into the urine.","Intravascular volume falls, so the urine is concentrated with a high specific gravity."]],
  ["OB-142","ASSOCIATION","Pregnancy physiology","31 weeks pregnant with exertional breathlessness and normal exam — arterial blood gas","Compensated respiratory alkalosis",["Compensated respiratory acidosis","Uncompensated metabolic alkalosis","Mixed metabolic acidosis"],["Progesterone stimulates the respiratory centre and raises tidal volume.","PaCO2 falls to about 30 mm Hg, and pH rises slightly.","The kidneys excrete bicarbonate to compensate, and the mild dyspnea is physiologic."]],
  ["OB-143","ASSOCIATION","Pregnancy physiology","Well woman at 28 weeks with platelets 120,000 (160,000 in the first trimester) and normal tests","Hemodilution and sequestration",["Immune complex consumption","Platelet microthrombi","Low thromboxane production"],["Gestational thrombocytopenia is a mild fall in platelets late in pregnancy.","It comes from dilution by expanded plasma and pooling in the placenta.","It needs no treatment, and platelets recover after delivery."]],
  ["OB-144","ASSOCIATION","Pregnancy complications","27 weeks with BP 172/118, right upper quadrant pain and a liver hematoma — what she is at risk of","Seizures",["Pancreatitis","Interstitial nephritis","Variceal bleeding"],["Severe hypertension with liver injury is preeclampsia with severe features or HELLP syndrome.","Both can progress to eclampsia, new-onset seizures.","Magnesium sulfate prevents seizures, and delivery is the definitive treatment."]],
  ["OB-145","ASSOCIATION","Teratogens & congenital infection","Preterm small baby, large pale placenta, cord with abscess-like necrosis around the vessels — cause","Spirochete infection",["Rh incompatibility","ACE inhibitor exposure","Partial mole"],["Necrotising funisitis is characteristic of congenital syphilis.","Treponema pallidum crosses the placenta and causes placentomegaly, hydrops and stillbirth.","Prenatal screening and penicillin treatment prevent it."]],
  ["OB-146","MECHANISM","Pregnancy physiology","8 weeks pregnant — the main direct job of hCG","Keeps the corpus luteum alive",["Inhibits uterine contractions","Triggers prolactin release","Promotes implantation"],["Without hCG the corpus luteum would regress after about 14 days.","hCG binds LH receptors and keeps the corpus luteum making progesterone.","By about 10 weeks the placenta takes over progesterone production."]],
  ["OB-147","MECHANISM","Contraception & drugs","Postpartum hemorrhage with fist-sized clots, given tranexamic acid — mechanism","Blocks plasminogen activation",["Raises vitamin K factors","Releases von Willebrand factor","Contracts uterine muscle"],["Tranexamic acid is an antifibrinolytic lysine analog.","It stops plasminogen from being converted to plasmin, so fibrin clots are not dissolved.","Given within 3 hours, it lowers death from postpartum hemorrhage."]],
  ["OB-148","MECHANISM","Pregnancy complications","Chronic hypertension with new 2+ proteinuria and a small-for-dates fundus at 28 weeks — placental physiology","High resistance, low perfusion",["Low resistance, low perfusion","Low resistance, high perfusion","Normal resistance, low perfusion"],["In preeclampsia, trophoblast fails to remodel the spiral arteries.","The narrow arteries keep placental resistance high and blood flow low.","Less oxygen reaches the fetus, causing growth restriction."]],
  ["OB-149","ASSOCIATION","Pregnancy complications","37 weeks with hypertension, sudden painful bleeding and a firm, tender uterus","Premature placental separation",["Placenta over the cervix","Rupture of the uterus","Torn fetal vessels"],["Painful third-trimester bleeding with a hard uterus is placental abruption.","Hypertension and cocaine are the main risk factors.","It can cause fetal distress and DIC; placenta previa bleeds painlessly."]],
  ["OB-150","ASSOCIATION","Teratogens & congenital infection","2-day-old with tachypnea, sneezing, diarrhea, tremors and high-pitched crying — treatment if comfort fails","Morphine",["Naloxone","Flumazenil","Vitamin K"],["These are signs of neonatal abstinence syndrome from maternal opioid use.","Swaddling, feeding and a calm room come first.","If needed, an opioid such as morphine is given and tapered; naloxone could precipitate seizures."]],
  ["OB-151","ASSOCIATION","Pregnancy physiology","Healthy runner at 30 weeks, more tired than before — plasma volume, red cell mass, hemoglobin","Both up, hemoglobin down",["Both down, hemoglobin down","Both up, hemoglobin up","Plasma down, hemoglobin up"],["Plasma volume rises by about 50% in pregnancy.","Red cell mass rises by only about 25%.","The larger plasma rise dilutes hemoglobin, causing physiologic anemia of pregnancy."]],
  ["OB-152","ASSOCIATION","Teratogens & congenital infection","Woman with epilepsy on valproate plans pregnancy — fetal risk of her medication","Myelomeningocele",["Epiphyseal stippling","Nasal hypoplasia","Micrognathia"],["Valproate is the antiepileptic most strongly linked to neural tube defects.","It interferes with folate metabolism during neural tube closure in weeks 3 to 4.","Switching drugs before conception and high-dose folic acid lower the risk; stippled epiphyses suggest warfarin."]],
  ["OB-153","ASSOCIATION","Pregnancy complications","32 weeks, prior severe preeclampsia, worsening painful bleeding with constant pain","Placental separation from myometrium",["Placenta extending over the cervix","Trophoblast invading the myometrium","Rupture through uterine serosa"],["Painful bleeding with a tender, firm uterus is placental abruption.","Hypertensive disorders of pregnancy are a leading risk factor.","Placenta previa causes painless bleeding, and uterine rupture follows a prior uterine scar."]],
  ["OB-154","ASSOCIATION","Pregnancy complications","29 weeks with BP 160/100 and sudden right upper quadrant pain and vomiting — lab pattern","High ALT, high bilirubin, low platelets",["High ALT, normal bilirubin and platelets","Normal ALT, high bilirubin, low platelets","Normal ALT and bilirubin, low platelets"],["Right upper quadrant pain with hypertension in the third trimester suggests HELLP syndrome.","Microangiopathic hemolysis raises indirect bilirubin and LDH, and liver injury raises transaminases.","Platelets are consumed; the definitive treatment is delivery."]],
  ["OB-155","MECHANISM","Pregnancy complications","Twin pregnancy at 30 weeks with sudden edema, hypertension and oliguria, bland urine sediment","Intrarenal artery vasospasm",["Immune complexes in glomeruli","Interstitial inflammation","Stone obstructing a calyx"],["Twins raise the risk of preeclampsia, which here causes oliguria.","Widespread endothelial dysfunction causes vasospasm and lowers renal perfusion and GFR.","Glomerular endotheliosis is the characteristic renal lesion; there are no red cell casts."]],
  ["OB-156","ASSOCIATION","Teratogens & congenital infection","Woman with irregular periods has an abnormal AFP at '16 weeks' by her last period — most common cause","Wrong gestational age",["Fetal growth restriction","Fetal heart defect","Edwards syndrome"],["AFP normally rises steeply through the second trimester.","If the pregnancy is further along or less advanced than thought, the result looks abnormal.","Ultrasound dating is the first step after an abnormal quad screen."]],
  ["OB-157","ASSOCIATION","Pregnancy complications","Hyperemesis at 12 weeks; ultrasound shows bright snowstorm tissue with no sac — follow-up after evacuation","Serial beta-hCG",["Serial alpha-fetoprotein","Serial CA-125","Serial CEA"],["Snowstorm ultrasound with no fetus is a complete hydatidiform mole.","After suction evacuation, hCG is measured until it is undetectable.","A plateau or rise signals persistent gestational trophoblastic neoplasia; contraception prevents confusion from a new pregnancy."]],
  ["OB-158","MECHANISM","Pregnancy complications","36 weeks with BP 154/102 and 2+ protein — factor with decreased activity","VEGF",["Endothelin","Thromboxane A2","hCG"],["Preeclampsia begins with abnormal placentation and placental ischemia.","The placenta releases sFlt-1, which binds and inactivates VEGF and placental growth factor.","Loss of these proangiogenic signals causes widespread endothelial dysfunction."]],
  ["OB-159","MECHANISM","Pregnancy physiology","35 weeks pregnant with prolactin several times normal but no milk — hormone preventing lactation","Progesterone",["Beta-hCG","Insulin","Thyroxine"],["Prolactin rises throughout pregnancy to prepare the breast.","High placental estrogen and progesterone block prolactin's effect on milk production.","After the placenta is delivered these fall and lactation begins."]],
  ["OB-160","ASSOCIATION","Pregnancy physiology","Ultrasound at 14 weeks shows twins, one boy and one girl — placentation","Dichorionic diamniotic",["Monochorionic diamniotic","Monochorionic monoamniotic","Dichorionic monoamniotic"],["Twins of different sexes must be dizygotic.","Dizygotic twins always have separate chorions and amnions.","Monozygotic twins vary with the day of splitting; later splits share more membranes."]],
  ["OB-161","ASSOCIATION","Pregnancy complications","Bleeding since delivery 9 weeks ago, then hemoptysis with lung nodules and very high hCG — histology","Sheets of trophoblast, no villi",["Diffusely swollen villi","Triploid fetal tissue","Whorled smooth muscle"],["Choriocarcinoma can follow a mole, abortion or normal pregnancy.","It shows sheets of cytotrophoblast and syncytiotrophoblast without chorionic villi.","It spreads by blood to the lungs, but responds well to methotrexate-based chemotherapy."]],
  ["OB-162","MECHANISM","Pregnancy physiology","Gallstones at 38 weeks in a woman with a normal scan a year earlier — mechanism","Cholesterol-rich bile, sluggish gallbladder",["More bile acids, faster emptying","More bilirubin, more phospholipid","More sodium, slower bile flow"],["Estrogen raises cholesterol secretion into bile, supersaturating it.","Progesterone relaxes smooth muscle and slows gallbladder emptying.","Bile stasis plus extra cholesterol makes stones form in pregnancy."]],
  ["OB-163","DEFICIENCY","Male hormones & development","46,XX newborn with clitoromegaly; the mother became virilised during the pregnancy","Aromatase",["21-hydroxylase","5α-reductase","17α-hydroxylase"],["Placental aromatase normally converts fetal androgens to estrogens.","Without it, androgens build up and virilise both the female fetus and the mother.","In 21-hydroxylase deficiency the mother is not virilised, because the excess androgen is aromatised."]],
  ["OB-164","ASSOCIATION","Prostate","Older man with hesitancy, straining and a stream that stops early, started on finasteride — target organ","Prostate gland",["Bladder detrusor","Bladder neck","External sphincter"],["These obstructive symptoms are from benign prostatic hyperplasia.","Finasteride inhibits 5α-reductase type 2 in the prostate, lowering DHT.","Less DHT shrinks the gland over months."]],
  ["OB-165","ASSOCIATION","Sexual health","Sudden erectile dysfunction during a time of arguments with his wife, morning erections intact","Psychological cause",["Vascular insufficiency","Antidepressant effect","Antihypertensive effect"],["Preserved nocturnal and morning erections show the vascular and nerve supply works.","A sudden start tied to a stressful situation points to a psychogenic cause.","Organic erectile dysfunction usually starts gradually and affects every setting."]],
  ["OB-166","ASSOCIATION","Testis & scrotum","Sudden left scrotal pain after a workout, high-riding testis, reduced Doppler flow — origin of the compromised artery","Abdominal aorta",["Internal iliac artery","External iliac artery","Internal pudendal artery"],["This is testicular torsion.","The testicular artery arises from the abdominal aorta just below the renal arteries, reflecting where the testis develops.","It must be detorsed within about 6 hours to save the testis."]],
  ["OB-167","MECHANISM","Male hormones & development","Teenager with gynecomastia, sparse body hair, oligospermia, and both testosterone and LH high","Androgen receptor dysfunction",["Leydig cell failure","Seminiferous tubule damage","Ejaculatory duct obstruction"],["High testosterone with high LH means the hormone is made but not acting.","Defective androgen receptors fail to feed back on the pituitary, so LH stays high.","Extra testosterone is aromatised to estradiol, causing gynecomastia; this is partial androgen insensitivity."]],
  ["OB-168","ASSOCIATION","Testis & scrotum","Painless hard nodule inseparable from the testis that does not transilluminate","Testicular cancer",["Hydrocele","Varicocele","Epididymitis"],["A solid intratesticular mass is cancer until proven otherwise.","Germ cell tumors peak in men aged 15 to 35.","Diagnosis is by ultrasound and tumor markers, then radical inguinal orchiectomy; never a scrotal biopsy."]],
  ["OB-169","DEFICIENCY","Male hormones & development","Boy with normal penis and male ducts, but a uterus and tubes found during hernia repair","Antimüllerian hormone",["Testosterone","Dihydrotestosterone","Luteinizing hormone"],["Sertoli cells make AMH, which makes the paramesonephric ducts regress.","Without AMH the uterus and tubes persist (persistent Müllerian duct syndrome).","Testosterone from Leydig cells still builds the male ducts and external genitalia."]],
  ["OB-170","ASSOCIATION","Male hormones & development","Mutation selectively impairs Sertoli cells, rest of the axis intact — hormone pattern","Low inhibin, high FSH",["High inhibin, normal FSH","Low testosterone, high LH","Low FSH, low LH"],["Sertoli cells secrete inhibin B, which feeds back to suppress FSH.","With Sertoli failure, inhibin falls and FSH rises.","Leydig cells are unaffected, so testosterone and LH stay normal."]],
  ["OB-171","MECHANISM","Prostate","Smooth, evenly enlarged prostate; after months of a drug the gland is smaller and the stream better","Finasteride",["Tamsulosin","Tadalafil","Tolterodine"],["5α-reductase inhibitors are the only BPH drugs that shrink the prostate.","They block conversion of testosterone to DHT, so benefit takes months.","Alpha-1 blockers such as tamsulosin act within days by relaxing smooth muscle, without shrinking the gland."]],
  ["OB-172","ASSOCIATION","Male hormones & development","Azoospermia, recurrent pneumonia, clubbing and absent vas deferens on both sides — confirming test","Sweat chloride",["Nasal cilia motility","Serum IgA","Alpha-1 antitrypsin level"],["Congenital bilateral absence of the vas deferens is a feature of cystic fibrosis.","Thick secretions block the developing Wolffian ducts.","Raised sweat chloride confirms CF; sperm can still be retrieved from the testis for IVF."]],
  ["OB-173","ASSOCIATION","Testis & scrotum","12-year-old with an inguinal testis fixed in the scrotum by surgery — lifelong risk","Seminoma",["Testicular torsion","Leydig cell tumor","Varicocele"],["Cryptorchidism raises the risk of testicular germ cell tumors, most often seminoma.","Orchiopexy makes the testis examinable but does not remove the risk completely.","Early surgery, ideally before 18 months, lowers the risk and preserves fertility."]],
  ["OB-174","MECHANISM","Sexual health","Painful erection lasting 8 hours after earlier brief episodes — action of the drug injected into the penis","Alpha-1 agonism",["Alpha-1 antagonism","Beta-2 agonism","Beta-1 stimulation"],["Priapism lasting over 4 hours is an emergency.","An alpha-1 agonist such as phenylephrine contracts cavernosal smooth muscle.","This lets blood drain out; aspiration of the corpora is also used."]],
  ["OB-175","MECHANISM","Male hormones & development","Tall 16-year-old with learning difficulties, gynecomastia and small testes — cause","Nondisjunction of the X",["Nondisjunction of the Y","FBN1 mutation","Expanded CGG repeat"],["This is Klinefelter syndrome, 47,XXY.","The extra X comes from meiotic nondisjunction in either parent.","FBN1 causes Marfan syndrome, and CGG repeat expansion causes fragile X."]],
  ["OB-176","ASSOCIATION","Prostate","BPH that improves and shrinks markedly on finasteride — likely histologic pattern","Mainly epithelial hyperplasia",["Mainly smooth muscle hyperplasia","Mainly collagen hyperplasia","Mixed muscle and collagen"],["DHT drives growth of the glandular epithelium of the prostate.","Lowering DHT with finasteride shrinks epithelial nodules most.","Stromal smooth muscle responds better to alpha-1 blockers."]],
  ["OB-177","ASSOCIATION","Testis & scrotum","Infant with scrotal fluid that enlarges on crying — what the same defect can cause","Indirect inguinal hernia",["Direct inguinal hernia","Femoral hernia","Testicular torsion"],["A communicating hydrocele means the processus vaginalis stays open.","Peritoneal fluid enters the scrotum, so swelling changes with straining.","Bowel can enter the same canal, causing an indirect hernia, so these are repaired surgically."]],
  ["OB-178","ASSOCIATION","Sexual health","Man choosing vasectomy — what to expect in the first months","Viable sperm in the ejaculate",["Much less ejaculate volume","Lower testosterone levels","Less sexual interest"],["Sperm stored beyond the cut remain for up to 3 months or about 20 ejaculations.","Other contraception is needed until a semen test shows no sperm.","Testosterone and ejaculate volume are unchanged, because sperm make up little of the volume."]],
  ["OB-179","ASSOCIATION","Prostate","Prostate cancer with no gland formation and enlarged iliac nodes — grade and stage","High grade, high stage",["Low grade, low stage","High grade, low stage","Low grade, high stage"],["The Gleason score is based on gland architecture, and absent glands is the highest pattern.","Stage depends on spread, and regional node involvement raises it.","Stage is the stronger prognostic factor in cancer generally."]],
  ["OB-180","ASSOCIATION","Prostate","Bilateral orchiectomy for germ cell tumors — expected effect on the prostate","Smaller glandular volume",["More stromal volume","Higher bone density","More lean body mass"],["Removing both testes removes most testosterone and therefore DHT.","The androgen-dependent glandular prostate atrophies.","Loss of androgens also lowers bone density and muscle mass and increases fat."]],
  ["OB-181","ASSOCIATION","Male hormones & development","Tall 17-year-old with learning problems, painful gynecomastia and small firm testes — lab finding","Raised FSH",["Raised prolactin","Raised beta-hCG","Low estradiol"],["Klinefelter syndrome destroys the seminiferous tubules (hyalinisation).","Inhibin B falls, so FSH rises, and Leydig dysfunction lowers testosterone and raises LH.","The estrogen-to-testosterone ratio rises, causing gynecomastia."]],
  ["OB-182","ASSOCIATION","Prostate","Older man with fever, dysuria, perineal pain and an exquisitely tender prostate","Escherichia coli",["Chlamydia trachomatis","Neisseria gonorrhoeae","Staphylococcus aureus"],["Acute bacterial prostatitis in older men is usually from gram-negative rods such as E. coli.","Prostate massage is avoided because it can spread bacteria into the blood.","In younger sexually active men, chlamydia and gonorrhea are more common."]],
  ["OB-183","ASSOCIATION","Sexual health","After a heart attack and stent he cannot keep erections with his partner, but libido and night erections are normal","Performance anxiety",["Beta-blocker side effect","Aortoiliac occlusion","Testosterone deficiency"],["Normal nocturnal erections rule out a vascular or hormonal cause.","Fear of another cardiac event during sex is common after an MI.","Reassurance that sex is safe once exercise is tolerated helps; PDE5 inhibitors are fine without nitrates."]],
  ["OB-184","ASSOCIATION","Testis & scrotum","Warm red tender hemiscrotum from a superficial scrotal abscess — draining nodes","Superficial inguinal",["Para-aortic","Common iliac","Inferior mesenteric"],["Scrotal skin drains to the superficial inguinal nodes.","The testis itself drains to the para-aortic nodes, following its descent.","An intact cremasteric reflex here argues against torsion."]],
  ["OB-185","MECHANISM","Prostate","Elderly man with hesitancy and bone metastases of adenocarcinoma — drug mechanism that would help","Inhibition of 17α-hydroxylase",["Activation of the androgen receptor","Activation of the LH receptor","Blockade of the estrogen receptor"],["Prostate cancer depends on androgens.","Abiraterone blocks CYP17 (17α-hydroxylase and 17,20-lyase), cutting androgen synthesis in the testes, adrenals and tumor.","Prednisone is given with it to replace cortisol and limit mineralocorticoid excess."]],
  ["OB-186","MECHANISM","Male hormones & development","Male whose urethral folds fail to fuse — resulting anomaly","Hypospadias",["Epispadias","Cryptorchidism","Bifid scrotum"],["In males the urethral folds fuse to close the penile urethra.","Failure leaves the urethral opening on the ventral (underside) surface.","Epispadias, an opening on the dorsal surface, comes from faulty positioning of the genital tubercle."]],
  ["OB-187","SIDE_EFFECT","Sexual health","Heart failure patient with low libido, poor erections and new gynecomastia after starting a diuretic","Androgen receptor blockade",["Less hepatic estrogen breakdown","Lower pituitary gonadotropins","More adrenal estrogen"],["Spironolactone blocks mineralocorticoid and androgen receptors.","Antiandrogen effects cause gynecomastia, low libido and erectile dysfunction.","Eplerenone is more selective and avoids these effects."]],
  ["OB-188","ASSOCIATION","Testis & scrotum","Sudden severe scrotal pain after soccer in a man treated for gonorrhea twice — exam finding","Absent cremasteric reflex",["Swelling grows with coughing","Pain eases when lifted","Mass transilluminates"],["Abrupt severe pain with a high-riding testis is torsion despite his STI history.","The cremasteric reflex is usually absent on the affected side.","Pain relief on lifting the testis (Prehn sign) favours epididymitis instead."]],
  ["OB-189","ASSOCIATION","Male hormones & development","Muscular man with small testes, low sperm count and normal testosterone","Anabolic steroid use",["Klinefelter syndrome","Kallmann syndrome","Hyperprolactinemia"],["Exogenous androgens suppress LH and FSH by negative feedback.","Low FSH and low intratesticular testosterone stop spermatogenesis, so the testes shrink.","Serum testosterone looks normal or high because of the drug."]],
  ["OB-190","ASSOCIATION","Sexual health","Elderly man laughs nervously and says he cannot get an erection — best first response","Normalise it and thank him",["Name his discomfort","Warn about drug side effects","Mention his age limits treatment"],["Patients often find sexual problems hard to raise.","Saying the problem is common and that mentioning it was right puts him at ease.","Once he is comfortable, take a full history; note his nitroglycerin rules out PDE5 inhibitors."]],
  ["OB-191","ASSOCIATION","Testis & scrotum","2-week-old with painless soft scrotal swelling that glows brightly with a penlight — fluid lies within","Tunica vaginalis",["Internal spermatic fascia","Cremasteric fascia","Epididymal head"],["A hydrocele is fluid within the tunica vaginalis around the testis.","The tunica vaginalis is the remnant of the processus vaginalis.","Most newborn hydroceles resolve by 12 to 18 months."]],
  ["OB-192","ASSOCIATION","Sexual health","Man avoids sex with an attractive partner; admits he ejaculates within a minute and feels no control","Premature ejaculation",["Erectile disorder","Low desire disorder","Depressive dysfunction"],["Premature ejaculation is ejaculation within about a minute of penetration, before it is wanted.","Shame can make men avoid sex, which looks like low desire.","SSRIs and behavioural techniques are used to treat it."]],
  ["OB-193","ASSOCIATION","Male hormones & development","46,XY fetus with complete androgen insensitivity — internal and external genitalia","No internal ducts, female external",["Uterus and tubes, ambiguous external","Vas deferens, female external","No internal ducts, male external"],["Sertoli cells still make AMH, so Müllerian ducts regress.","Without androgen action, Wolffian ducts also regress, so there are no internal ducts.","External genitalia are female with a blind-ending vagina; testes are in the abdomen or labia."]],
  ["OB-194","MECHANISM","Prostate","Metastatic prostate cancer on a GnRH agonist develops bone pain; flutamide is added — mechanism","Androgen receptor blockade",["Less Leydig cell stimulation","Less peripheral conversion","Less androgen synthesis"],["Flutamide is a nonsteroidal competitive androgen receptor antagonist.","A GnRH agonist first causes a testosterone flare, which can worsen bone pain.","Combining the two gives fuller androgen blockade."]],
  ["OB-195","ASSOCIATION","Testis & scrotum","Low sperm count with antisperm antibodies after testicular trauma — cells forming the damaged barrier","Sertoli cells",["Leydig cells","Primary spermatocytes","Tunica albuginea"],["Tight junctions between Sertoli cells form the blood-testis barrier.","It isolates developing sperm, which appear after immune tolerance forms, from the immune system.","Trauma or surgery that breaks it allows antisperm antibodies to form."]],
  ["OB-196","MECHANISM","Testis & scrotum","Teen with brief bouts of scrotal pain for weeks, now severe; removed testis shows hemorrhagic infarction — cause","Abnormally mobile testis",["Pampiniform plexus clot","Fluid in the scrotal sac","Bacteria from the urine"],["A bell-clapper deformity leaves the testis poorly fixed to the tunica vaginalis.","It can twist and untwist, causing intermittent pain before full torsion.","Twisting blocks venous outflow first, so the testis becomes hemorrhagic; the other side is fixed too."]],
  ["OB-197","SIDE_EFFECT","Sexual health","Painful 6-hour erection in a man with depression and insomnia — likely drug","Trazodone",["Bupropion","Citalopram","Imipramine"],["Trazodone is a sedating antidepressant often used for insomnia.","Its alpha-1 blocking effect can trap blood in the corpora, causing priapism.","Bupropion has the least sexual side effects among antidepressants."]],
  ["OB-198","ASSOCIATION","Pelvic anatomy","Pelvic fracture from a car crash with a full bladder he cannot empty — urethral segment torn","Membranous urethra",["Penile urethra","Bulbar urethra","Prostatic urethra"],["Posterior urethral injury goes with pelvic fractures.","The membranous urethra, passing through the urogenital diaphragm, is the weakest point.","Blood at the meatus and a high-riding prostate are signs; do not pass a catheter before a urethrogram."]],
  ["OB-199","ASSOCIATION","Testis & scrotum","Young man with weight loss, tachycardia, a mild goitre and a painless enlarged testis — tumor product","Human chorionic gonadotropin",["Alpha-fetoprotein","Placental alkaline phosphatase","Follicle-stimulating hormone"],["Choriocarcinoma and some mixed germ cell tumors secrete large amounts of hCG.","hCG shares an alpha subunit with TSH and weakly stimulates the TSH receptor.","Very high levels cause paraneoplastic hyperthyroidism and gynecomastia."]],
  ["OB-200","ASSOCIATION","Sexual health","Man with ALS mentions things are 'different' with his wife but no depression — best response","Ask about intimacy openly",["Suggest couples therapy","Say ups and downs are normal","Tell him to give it time"],["Chronic illness often affects intimacy and sexual function.","Normalising the topic and inviting him to say more opens a hard conversation.","Jumping to advice or reassurance can close the topic before the problem is known."]],
  ["OB-201","ASSOCIATION","Testis & scrotum","Solid testicular mass in a 23-year-old — first lymph node group for spread","Para-aortic",["Superficial inguinal","Deep inguinal","External iliac"],["Testicular lymphatics follow the gonadal vessels to the retroperitoneum.","Germ cell tumors therefore spread first to the para-aortic nodes.","Scrotal skin drains to the superficial inguinal nodes, which is why scrotal biopsy is avoided."]],
  ["OB-202","ASSOCIATION","Male hormones & development","Tall man with gynecomastia, sparse beard, small firm testes and low libido — treatment","Testosterone",["Gonadotropins","PDE5 inhibitor","Aromatase inhibitor"],["Klinefelter syndrome causes primary hypogonadism with low testosterone.","Testosterone replacement improves libido, energy, bone density and secondary sex characteristics.","Gonadotropins cannot work because the testes themselves fail."]],
  ["OB-203","ASSOCIATION","Prostate","Older man with BPH symptoms and blood pressure above goal on two drugs — single best addition","Doxazosin",["Tamsulosin","Finasteride","Hydrochlorothiazide"],["Nonselective alpha-1 blockers relax prostatic smooth muscle and vascular smooth muscle.","Doxazosin, terazosin and prazosin can therefore treat BPH and hypertension together.","Tamsulosin is alpha-1A selective, so it barely lowers blood pressure."]],
  ["OB-204","ASSOCIATION","Testis & scrotum","18-year-old with posterior testicular tenderness, intact cremasteric reflex and pyuria — risk factor","Unprotected sex",["Missed childhood vaccines","Poor testicular fixation","High gonadal venous pressure"],["Tenderness of the posterior and superior testis with an intact cremasteric reflex is epididymitis.","Under 35 it is usually from chlamydia or gonorrhea.","In older men or those practising insertive anal sex, enteric organisms such as E. coli are more common."]],
  ["OB-205","MECHANISM","Prostate","Rising PSA after prostatectomy; bicalutamide is started along with buserelin — reason","Blocks the initial flare",["Blocks adrenal androgens","Induces tumor apoptosis","Prevents hot flashes"],["GnRH agonists such as buserelin first stimulate the pituitary, raising LH and testosterone.","This flare can worsen bone pain or urinary obstruction.","An androgen receptor blocker like bicalutamide is given for the first weeks to cover it."]],
  ["OB-206","ASSOCIATION","Prostate","Hematuria with a hard prostate; biopsy shows crowded small glands with large nucleoli","Prostate adenocarcinoma",["Benign prostatic hyperplasia","Chronic prostatitis","Urothelial carcinoma"],["Prostate cancer shows small, crowded glands lined by one cell layer with prominent nucleoli.","Basal cells are absent, unlike benign glands.","It arises mostly in the peripheral zone, so it is often felt on rectal exam."]],
  ["OB-207","MECHANISM","Sexual health","Man with sickle cell disease and a rigid shaft with soft glans; cavernosal blood is dark and acidic","Impaired venous outflow",["Raised arterial inflow","Tunica albuginea fibrosis","Raised sympathetic tone"],["Ischemic (low-flow) priapism is the common type and an emergency.","Sickled cells block venous outflow from the corpora cavernosa.","Blood gas shows hypoxia and acidosis; treat with aspiration and phenylephrine."]],
  ["OB-208","ASSOCIATION","Prostate","Elderly man dies of a pulmonary embolism; months of back pain and bone-forming vertebral lesions — biopsy of the lesion","Irregular glands, large nucleoli",["Clear cells in sheets","Pigmented pleomorphic cells","Papillae with psammoma bodies"],["Osteoblastic bone metastases in an older man are classic for prostate cancer.","It spreads to the spine through the vertebral venous plexus.","Malignancy also raises the risk of venous thromboembolism."]],
  ["OB-209","ASSOCIATION","Testis & scrotum","Painless solid partly necrotic testicular mass with high AFP and LDH","Nonseminomatous germ cell tumor",["Pure seminoma","Leydig cell tumor","Testicular lymphoma"],["Raised AFP excludes pure seminoma.","Yolk sac elements in a nonseminomatous germ cell tumor secrete AFP.","Seminomas may raise hCG and LDH but never AFP."]],
  ["OB-210","ASSOCIATION","Prostate","Older smoker straining to urinate with osteoblastic lumbar lesions — route of spread","Prostatic venous plexus",["Internal iliac nodes","Azygos vein","Para-aortic nodes"],["The prostatic venous plexus connects with the valveless vertebral venous plexus (Batson plexus).","Tumor cells reach the lumbar spine and pelvis this way.","This explains why prostate cancer metastases are so often vertebral."]],
  ["OB-211","ASSOCIATION","Prostate","Very high PSA, father died of prostate cancer, indurated prostate — biopsy technique","Transrectal multiple random cores",["Cystoscopic single central core","Transperineal needle aspiration","Transrectal single central core"],["Most prostate cancers arise in the peripheral zone, next to the rectum.","Transrectal ultrasound-guided core biopsies sample this zone.","Multiple systematic cores are taken because tumors are often multifocal."]],
  ["OB-212","ASSOCIATION","Male hormones & development","Normal sperm count but completely immotile sperm from abnormal tails — associated finding","Bronchiectasis",["Fat malabsorption","Coarctation of the aorta","Cleft lip"],["Primary ciliary dyskinesia is a dynein arm defect in cilia and flagella.","Poor mucociliary clearance causes sinusitis and bronchiectasis.","Half of patients have situs inversus (Kartagener syndrome)."]],
  ["OB-213","ASSOCIATION","Testis & scrotum","Orchiopexy for an inguinal testis — structure the testis passes through on its way to the scrotum","External oblique aponeurosis",["Transversalis fascia","Conjoint tendon","Femoral ring"],["The superficial inguinal ring is an opening in the external oblique aponeurosis.","The testis is brought through it into the scrotum and fixed.","The deep ring is in the transversalis fascia."]],
  ["OB-214","SIDE_EFFECT","Prostate","Radical prostatectomy where the nerves in the prostatic fascia are damaged — complication","Erectile dysfunction",["Fecal incontinence","Detrusor overactivity","Loss of cremasteric reflex"],["The cavernous nerves run in the neurovascular bundles beside the prostate.","They carry parasympathetic fibres from S2-S4 that cause erection.","Nerve-sparing surgery aims to protect them; incontinence comes from sphincter injury instead."]],
  ["OB-215","MECHANISM","Male hormones & development","Fatigue, low libido and erectile dysfunction with darkened skin, high glucose and an enlarged liver","Iron in the pituitary",["Adrenal autoimmunity","Ectopic ACTH","Aortoiliac atherosclerosis"],["This is hereditary hemochromatosis.","Iron deposits in pituitary gonadotroph cells cause hypogonadotropic hypogonadism.","It also damages the liver, pancreas, skin and heart; phlebotomy is the treatment."]],
];
